import { Dialog as DialogPrimitive } from "@base-ui-components/react/dialog";
import type { ComponentProps } from "react";

import { renderAsChild } from "../lib/as-child";
import { cn } from "../lib/cn";

export function Dialog({ ...props }: ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root {...props} />;
}

export interface DialogTriggerProps extends ComponentProps<typeof DialogPrimitive.Trigger> {
  /** Render as the single child element instead of a `<button>`, keeping the open behaviour. */
  asChild?: boolean;
}

export function DialogTrigger({ asChild, children, ...props }: DialogTriggerProps) {
  return (
    <DialogPrimitive.Trigger {...renderAsChild(asChild, children)} {...props}>
      {children}
    </DialogPrimitive.Trigger>
  );
}

export function DialogPortal({ ...props }: ComponentProps<typeof DialogPrimitive.Portal>) {
  return <DialogPrimitive.Portal {...props} />;
}

export interface DialogCloseProps extends ComponentProps<typeof DialogPrimitive.Close> {
  /** Render as the single child element instead of a `<button>`, keeping the close behaviour. */
  asChild?: boolean;
}

export function DialogClose({ asChild, children, ...props }: DialogCloseProps) {
  return (
    <DialogPrimitive.Close {...renderAsChild(asChild, children)} {...props}>
      {children}
    </DialogPrimitive.Close>
  );
}

/**
 * The scrim.
 *
 * Base UI calls this a Backdrop rather than an Overlay, and the name is the
 * better one: it is painted behind the popup and it is what a pointer press lands
 * on, which is exactly what a backdrop is for.
 */
export function DialogBackdrop({
  className,
  ...props
}: ComponentProps<typeof DialogPrimitive.Backdrop>) {
  return (
    <DialogPrimitive.Backdrop
      data-slot="dialog-backdrop"
      className={cn(
        // `data-starting-style` / `data-ending-style`, not `data-[state=open]`.
        // Base UI exposes the pre-animation state rather than the open state,
        // which is what lets an enter animation start *from* a style instead of
        // only running once the element is already visible.
        "fixed inset-0 z-50 bg-foreground/30 transition-opacity duration-standard data-[ending-style]:animate-fade-out data-[starting-style]:animate-fade-in",
        className,
      )}
      {...props}
    />
  );
}

/** Kept under the old name so existing call sites keep working. */
export const DialogOverlay = DialogBackdrop;

export function DialogContent({
  className,
  children,
  ...props
}: ComponentProps<typeof DialogPrimitive.Popup>) {
  return (
    // The portal, the backdrop and the viewport are all inside `DialogContent`, so
    // a dialog cannot be clipped by an ancestor's overflow and the consumer only
    // ever writes the panel. The exit animation works because Base UI keeps the
    // popup mounted while `data-ending-style` is present.
    <DialogPrimitive.Portal>
      <DialogBackdrop />
      {/* The viewport is the scroll container and the positioning frame. Without it
          a tall dialog on a short window is unscrollable, which is the case that
          breaks first on a laptop. */}
      <DialogPrimitive.Viewport
        data-slot="dialog-viewport"
        className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto p-4"
      >
        <DialogPrimitive.Popup
          data-slot="dialog-content"
          className={cn(
            "grid w-full max-w-md gap-5 rounded-xl border border-border bg-popover p-6 text-popover-foreground shadow-xl outline-none transition-[opacity,transform] duration-standard data-[ending-style]:animate-pop-out data-[starting-style]:animate-pop-in",
            className,
          )}
          {...props}
        >
          {children}
        </DialogPrimitive.Popup>
      </DialogPrimitive.Viewport>
    </DialogPrimitive.Portal>
  );
}

export function DialogHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div data-slot="dialog-header" className={cn("grid gap-1.5 pr-8", className)} {...props} />
  );
}

export function DialogFooter({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("flex flex-col gap-2 sm:flex-row sm:justify-end", className)}
      {...props}
    />
  );
}

export function DialogTitle({ className, ...props }: ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn("text-base leading-tight font-semibold", className)}
      {...props}
    />
  );
}

export function DialogDescription({
  className,
  ...props
}: ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

/**
 * Turning Forme's `asChild` into Base UI's `render`.
 *
 * Forme's public API is `asChild`, which is the shadcn convention: someone
 * copying a component into a project that already uses shadcn already knows it,
 * and changing it would mean relearning every trigger in every block.
 *
 * Base UI calls the same thing `render`, and the difference is that `render` also
 * accepts a function. `asChild` cannot, because the shadcn contract is "the one
 * child element", and a function is not an element.
 *
 * So this is a one-way adapter in a shared file rather than three copies of the
 * same conditional. Two reasons it is worth a file:
 *
 * - The check is the interesting part. `render` given `undefined` silently
 *   renders the component's own element; given a fragment or a string it merges
 *   props onto something that cannot take them. Returning `undefined` for the
 *   non-element cases turns a subtle runtime failure into the component behaving
 *   as if `asChild` were not set.
 * - When the primitives change, this is the one place to change. Three copies
 *   drift.
 */
import type { ReactElement, ReactNode } from "react";

/**
 * A single element `render` can merge its props onto.
 *
 * `React.isValidElement` is the test, spelled out here rather than imported: it
 * rejects strings, numbers, arrays and fragments, all of which are things a
 * caller might plausibly pass and none of which can receive a ref or an event
 * handler.
 */
export function asChildElement(
  child: ReactNode,
): ReactElement<Record<string, unknown>> | undefined {
  if (child === null || child === undefined || typeof child !== "object") return undefined;

  // `$$typeof` is React's element brand. Checking it directly rather than via
  // `React.isValidElement` keeps this file free of a React runtime import, which
  // matters because it ships to every consumer's project as part of every
  // install that uses `asChild`.
  if (!("$$typeof" in child) || typeof (child as { type?: unknown }).type !== "function") {
    // A fragment has `type` as a symbol, and an intrinsic element has it as a
    // string. Both are handled by the check above falling through; this branch
    // exists only to document that they are deliberately not supported.
    return undefined;
  }

  return child as ReactElement<Record<string, unknown>>;
}

/**
 * The pair a component needs to spread.
 *
 * Spread both onto the primitive:
 *
 * ```tsx
 * <DialogTrigger {...renderAsChild(asChild, children)} />
 * ```
 */
export function renderAsChild(
  asChild: boolean | undefined,
  children: ReactNode,
): { render?: ReactElement<Record<string, unknown>> } {
  if (!asChild) return {};
  const element = asChildElement(children);
  // `asChild` with no element to merge onto is a mistake at the call site. The
  // primitive then renders its own element, which looks correct until someone
  // clicks it and nothing happens.
  return element ? { render: element } : {};
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

/**
 * Forme's type styles, so tailwind-merge stops treating them as colours.
 *
 * The bug this prevents, which was live in this file for a while and is
 * invisible in the source: `tailwind-merge` has no view of a Tailwind theme. Any
 * `text-*` utility it does not recognise as one of Tailwind's built-in font sizes
 * is assumed to be a text **colour**. So on a button whose classes were
 * `p-2 text-body bg-button-primary text-white`, it saw two text-colours, applied
 * last-write-wins, and silently dropped `text-body`. The class was in the source,
 * the utility was in the stylesheet, the DOM had it on the element — and the
 * button rendered at 16px instead of 14px. Nothing errored.
 *
 * Registering them under `font-size` is the fix, and every name added to
 * typography.css has to be added here too. That duplication is the price: the
 * alternative is a type utility that a caller can delete by accident.
 *
 * If you rename or add a type style in foundation.css, mirror it in this list.
 */
const TEXT_FAMILIES = [
  "body",
  "body-2",
  "caption-1",
  "caption-2",
  "title-1",
  "title-2",
  "title-3",
  "headline",
] as const;

const TEXT_WEIGHTS = ["regular", "medium", "semibold", "bold"] as const;

const TEXT_STYLES = TEXT_FAMILIES.flatMap((family) =>
  TEXT_WEIGHTS.map((weight) => `${family}-${weight}`),
);

const merge = extendTailwindMerge({
  extend: {
    classGroups: {
      "font-size": [{ text: TEXT_STYLES }],
    },
  },
});

/**
 * Merges class names, letting a caller's `className` win over a component's
 * defaults. Without the merge step a `px-4` from the component and a `px-6` from
 * the caller would both reach the browser and the winner would be whichever came
 * last in the stylesheet rather than whichever the caller meant.
 */
export function cn(...inputs: ClassValue[]): string {
  return merge(clsx(inputs));
}
